namespace ccls {
struct BinaryReader {
  const char *p_;

  BinaryReader(std::string_view buf) : p_(buf.data()) {}
  template <typename T> T get() {
    T ret;
    memcpy(&ret, p_, sizeof(T));
    p_ += sizeof(T);
    return ret;
  }
  uint64_t varUInt() {
    auto x = *reinterpret_cast<const uint8_t *>(p_++);
    if (x < 253)
      return x;
    if (x == 253)
      return get<uint16_t>();
    if (x == 254)
      return get<uint32_t>();
    return get<uint64_t>();
  }
  int64_t varInt() {
    uint64_t x = varUInt();
    return int64_t(x >> 1 ^ -(x & 1));
  }
  const char *getString() {
    const char *ret = p_;
    while (*p_)
      p_++;
    p_++;
    return ret;
  }
};
} // namespace ccls

namespace ccls {
struct BinaryWriter {
  std::string buf_;

  template <typename T> void pack(T x) {
    auto i = buf_.size();
    buf_.resize(i + sizeof(x));
    memcpy(buf_.data() + i, &x, sizeof(x));
  }

  void varUInt(uint64_t n) {
    if (n < 253)
      pack<uint8_t>(n);
    else if (n < 65536) {
      pack<uint8_t>(253);
      pack<uint16_t>(n);
    } else if (n < 4294967296) {
      pack<uint8_t>(254);
      pack<uint32_t>(n);
    } else {
      pack<uint8_t>(255);
      pack<uint64_t>(n);
    }
  }
  void varInt(int64_t n) { varUInt(uint64_t(n) << 1 ^ n >> 63); }
  std::string take() { return std::move(buf_); }

  void string(const char *x) { string(x, strlen(x)); }
  void string(const char *x, size_t len) {
    auto i = buf_.size();
    buf_.resize(i + len + 1);
    memcpy(buf_.data() + i, x, len);
  }
};
