// Instantiate a compatible Node type for ccls::flattenHierarchy: it must have
//   - member `std::vector<Node> children;`
//   - member `ccls::Location location;`
struct FH_Node {
  ccls::Location location;
  std::vector<FH_Node> children;
};

// Generate a small bounded hierarchy using a single seeded pseudo-random
// generator to avoid repeated FUZZ_PARAM calls in loops.
unsigned int seed = *FUZZ_PARAM(unsigned int);
auto nextRand = [&seed]() {
  // Simple LCG: new = (a*old + c)
  seed = seed * 1664525u + 1013904223u;
  return seed;
};

// Randomly choose whether root is disengaged; if disengaged, result must be empty.
bool disengage = (nextRand() & 1u) != 0u;

std::optional<FH_Node> rootOpt;
if (!disengage) {
  // Configure breadth/depth with tight bounds for performance.
  int maxDepth = 1 + int((nextRand() % 3));       // 1..3
  int maxBreadth = 1 + int((nextRand() % 5));     // 1..5 children per node
  int maxNodes = 1 + int((nextRand() % 32));      // cap total nodes ~32

  // Helper to create a URI string; sometimes empty to exercise filtering.
  auto makeUri = [&]() -> std::string {
    // 1/4 chance to be empty
    if ((nextRand() % 4) == 0) return std::string();
    // Else generate a short pseudo path-like string from seed
    std::string s;
    s.reserve(16);
    s.push_back('/');
    for (int i = 0; i < 8; ++i) {
      char ch = char('a' + (nextRand() % 26));
      s.push_back(ch);
    }
    s += ".cc";
    return s;
  };

  // Initialize root
  rootOpt.emplace();
  rootOpt->location.uri.raw_uri = makeUri();

  // Iteratively build children up to bounds
  std::vector<FH_Node*> frontier;
  frontier.push_back(&*rootOpt);
  int nodesMade = 1;
  for (int depth = 0; depth < maxDepth && nodesMade < maxNodes; ++depth) {
    std::vector<FH_Node*> nextFrontier;
    for (FH_Node* parent : frontier) {
      // Breadth for this parent
      int b = 1 + int(nextRand() % (unsigned)maxBreadth);
      for (int i = 0; i < b && nodesMade < maxNodes; ++i) {
        FH_Node child;
        child.location.uri.raw_uri = makeUri();
        // ranges can stay default; ordering and equality are still well-defined
        parent->children.emplace_back(std::move(child));
        nextFrontier.push_back(&parent->children.back());
        ++nodesMade;
      }
    }
    frontier.swap(nextFrontier);
    if (frontier.empty()) break;
  }
}

// Call target function under test
auto out = ccls::flattenHierarchy<FH_Node>(rootOpt);

// Validate API properties:
// - If root is disengaged, result should be empty.
if (!rootOpt.has_value()) {
  if (!out.empty()) { FUZZ_BAIL(); }
} else {
  // - All returned locations must have non-empty URIs
  for (size_t i = 0; i < out.size(); ++i) {
    if (out[i].uri.raw_uri.size() == 0) { FUZZ_BAIL(); }
