MAX_TOTAL = 4096

def _weighted_choice(rng: random.Random, items: List[str], weights: List[int]) -> str:
    return rng.choices(items, weights=weights, k=1)[0]

def _repeat(rng: random.Random, s: str, min_times: int, max_times: int) -> str:
    return s * rng.randint(min_times, max_times)

def _rand_ascii(rng: random.Random, min_len: int, max_len: int) -> str:
    length = rng.randint(min_len, max_len)
    alphabet = string.ascii_letters + string.digits + " _-.,:+/\\()[]{}#@!$%^&*~?="
    return ''.join(rng.choice(alphabet) for _ in range(length))

def _rand_unicode(rng: random.Random, min_len: int, max_len: int) -> str:
    # Mix common multi-byte UTF-8 sequences with ASCII
    pools = [
        "àáâãäåæçèéêëìíîïðñòóôõö÷øùúûüýþÿ",
        "ășțîâĂȘȚÎÂ",
        "αβγδεζηθικλμνξοπρστυφχψω",
        "абвгдеёжзийклмнопрстуфхцчшщъыьэюя",
        "漢字仮名かなカナ一二三四五六七八九十",
        "🙂🙃😉😊😇🥰😍🤩😘😗😙😚😋😛😜🤪🤨🧐🤓",
    ]
    base = _rand_ascii(rng, min_len//2, max_len//2)
    uni = ''.join(rng.choice(pools[rng.randrange(len(pools))]) for _ in range(rng.randint(1, (max_len - len(base)) // 2 + 1)))
    s = base + uni
    # Ensure within bounds
    if len(s) < min_len:
        s += _rand_ascii(rng, min_len - len(s), min_len - len(s))
    if len(s) > max_len:
        s = s[:max_len]
    return s

