        # Avoid empty segment
        name = name if name else "x"
        parts.append(name)
    sep = _weighted_choice(rng, ["/", "\\"], [3, 2])
    return _weighted_choice(rng, roots, [4,2,2,2,1,1]) + sep.join(parts)

def _typical_words(rng: random.Random) -> str:
    words = [
        "include", "blacklist", "whitelist", "folder", "project", "index",
        "completion", "diagnostics", "symbol", "location", "uri", "json",
        "binary", "format", "range", "position", "variable", "function",
        "class", "namespace", "template", "operator", "snippet",
    ]
    k = rng.randint(2, 8)
    return ' '.join(rng.choices(words, k=k))

def _make_case_variants(rng: random.Random, s: str) -> str:
    modes = [str.lower, str.upper, str.title]
    s = _weighted_choice(rng, [m(s) for m in modes], [3,2,1])
    # Insert camel/snake variants
    if rng.random() < 0.4:
        s = s.replace(' ', _weighted_choice(rng, ['_', '-', ''], [3,2,1]))
    return s

def _regex_like(rng: random.Random) -> str:
    # Pattern-like string to trigger different matcher paths
    atoms = [r".*", r".+", r"^", r"$", r"[A-Za-z_][A-Za-z0-9_]*", r"\b", r"\s*", r"\d+", r"(foo|bar)"]
    s = ''.join(rng.choice(atoms) for _ in range(rng.randint(1, 4)))
    # Add literals
    if rng.random() < 0.6:
        s += _rand_ascii(rng, 1, 6)
    return s

def _compose_payload(rng: random.Random) -> str:
    # Build an "interesting" C-string payload likely to exercise path/escaping and general text handling
    kind = _weighted_choice(rng,
                            ["path", "unicode", "ascii", "regex", "words", "long"],
                            [30, 15, 20, 10, 15, 10])
    if kind == "path":
        s = _path_like(rng)
        # maybe add query/fragment
        if rng.random() < 0.3:
            s += "?q=" + _rand_ascii(rng, 1, 8)
        if rng.random() < 0.2:
            s += "#" + _rand_ascii(rng, 1, 6)
        return s
    if kind == "unicode":
        return _rand_unicode(rng, 6, 64)
    if kind == "ascii":
        return _rand_ascii(rng, 1, 128)
    if kind == "regex":
        return _regex_like(rng)
    if kind == "words":
        return _make_case_variants(rng, _typical_words(rng))
    # long
    base = _rand_ascii(rng, 16, 64)
    suffix = _weighted_choice(rng, [".h", ".hpp", ".c", ".cc", ".cpp", ".inc", ".json", ".bin"], [2,2,2,2,3,1,1,1])
    repeated = _repeat(rng, base + suffix + "\n", 1, 10)
    return repeated.strip()

def generate(seed: int) -> bytes:
    rng = random.Random(seed)
    s = _compose_payload(rng)
    # Ensure no embedded NULs and UTF-8 validity: Python str is Unicode; encode to UTF-8
    b = s.encode('utf-8', errors='strict')
    # Truncate to leave space for harness overhead if any; but FUZZ_PARAM_STR consumes as string
    if len(b) > MAX_TOTAL:
        b = b[:MAX_TOTAL]
    # Guarantee at least one byte and avoid accidental empty string
    if not b:
        b = b"x"
    # Do not append a NUL here; FUZZ_PARAM_STR provides std::string which is NUL-terminated in c_str().
    return b
